// Remove only small/slender connected color fragments hugging the external rim.
// Whole interior components and holes are kept, irrespective of color.
function edgeFragmentContours(d){const chunks=d.split(/(?=M\s)/).filter(s=>s.trim());return chunks.map(text=>{const t=text.match(/[MLQCZmlqcz]|[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:e[-+]?\d+)?/gi)||[];let i=0,command='',last=[0,0],first=[0,0],points=[];const mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2];const dist=(p,a,b)=>{const x=b[0]-a[0],y=b[1]-a[1],u=Math.max(0,Math.min(1,((p[0]-a[0])*x+(p[1]-a[1])*y)/(x*x+y*y||1)));return Math.hypot(p[0]-a[0]-u*x,p[1]-a[1]-u*y);};function add(p){if(!points.length||Math.hypot(p[0]-points.at(-1)[0],p[1]-points.at(-1)[1])>1e-8)points.push(p);}function pair(){const p=[+t[i++],+t[i++]];if(p.some(n=>!Number.isFinite(n)))throw Error('Invalid perimeter fragment coordinates.');return p;}function quad(a,b,c,n=0){if(n>14||dist(b,a,c)<.15){add(c);return;}const ab=mid(a,b),bc=mid(b,c),m=mid(ab,bc);quad(a,ab,m,n+1);quad(m,bc,c,n+1);}function cubic(a,b,c,e,n=0){if(n>14||Math.max(dist(b,a,e),dist(c,a,e))<.15){add(e);return;}const ab=mid(a,b),bc=mid(b,c),ce=mid(c,e),abc=mid(ab,bc),bce=mid(bc,ce),m=mid(abc,bce);cubic(a,ab,abc,m,n+1);cubic(m,bce,ce,e,n+1);}while(i<t.length){if(/^[a-z]$/i.test(t[i]))command=t[i++];if(command==='M'){last=pair();first=last;add(last);command='L';}else if(command==='L'){last=pair();add(last);}else if(command==='Q'){const b=pair(),c=pair();quad(last,b,c);last=c;}else if(command==='C'){const a=pair(),b=pair(),e=pair();cubic(last,a,b,e);last=e;}else if(command==='Z'||command==='z'){last=first;command='';}else throw Error('Unsupported perimeter fragment command.');}if(points.length>1&&Math.hypot(points[0][0]-points.at(-1)[0],points[0][1]-points.at(-1)[1])<1e-8)points.pop();let area=0,length=0;for(let j=0;j<points.length;j++){const a=points[j],b=points[(j+1)%points.length];area+=a[0]*b[1]-b[0]*a[1];length+=Math.hypot(a[0]-b[0],a[1]-b[1]);}return {d:text.trim(),points,area:area/2,length};});}
function edgePointInside(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
function cleanupEdgeFragments(groups,outlineD,edgeFill,enabled=true){const result=new Map([...groups].map(([fill,ds])=>[fill,ds.slice()]));const stats={enabled,removedComponents:0,recoloredAreaPx2:0,removedRegionsD:'',bandPx:3};if(!enabled||!outlineD||!edgeFill)return {groups:result,stats};const band=3,cell=4,grid=new Map(),outline=edgeFragmentContours(outlineD);let perimeter=0;
 for(const contour of outline){perimeter+=contour.length;for(let i=0;i<contour.points.length;i++){const a=contour.points[i],b=contour.points[(i+1)%contour.points.length],segment={a,b};for(let y=Math.floor((Math.min(a[1],b[1])-band)/cell);y<=Math.floor((Math.max(a[1],b[1])+band)/cell);y++)for(let x=Math.floor((Math.min(a[0],b[0])-band)/cell);x<=Math.floor((Math.max(a[0],b[0])+band)/cell);x++){const key=x+','+y;if(!grid.has(key))grid.set(key,[]);grid.get(key).push(segment);}}}
 const near=p=>{const segments=grid.get(Math.floor(p[0]/cell)+','+Math.floor(p[1]/cell))||[];return segments.some(({a,b})=>{const x=b[0]-a[0],y=b[1]-a[1],u=Math.max(0,Math.min(1,((p[0]-a[0])*x+(p[1]-a[1])*y)/(x*x+y*y||1)));return Math.hypot(p[0]-a[0]-u*x,p[1]-a[1]-u*y)<=band;});};
 const removed=[];for(const [fill,ds]of result){if(fill===edgeFill)continue;const contours=ds.flatMap(edgeFragmentContours),components=contours.filter(c=>c.area>=-1e-7).map(c=>({outer:c,contours:[c]})),unmatched=[];for(const hole of contours.filter(c=>c.area<-1e-7)){const owners=components.filter(c=>c.outer.area>Math.abs(hole.area)&&hole.points.length&&edgePointInside(hole.points[0],c.outer.points)).sort((a,b)=>a.outer.area-b.outer.area);if(owners.length)owners[0].contours.push(hole);else unmatched.push(hole);}
 const removedSet=new Set();const kept=[];for(const component of components){const area=Math.abs(component.contours.reduce((sum,c)=>sum+c.area,0)),length=component.contours.reduce((sum,c)=>sum+c.length,0);let artifact=length>0&&area<=Math.min(256,Math.max(32,perimeter*.25))&&area/length<=1.25&&length<perimeter*.5;
 if(artifact)for(const contour of component.contours){for(let i=0;i<contour.points.length&&artifact;i++){const a=contour.points[i],b=contour.points[(i+1)%contour.points.length],steps=Math.max(1,Math.ceil(Math.hypot(a[0]-b[0],a[1]-b[1])/1.25));for(let k=0;k<=steps;k++){const u=k/steps;if(!near([a[0]+(b[0]-a[0])*u,a[1]+(b[1]-a[1])*u])){artifact=false;break;}}}if(!artifact)break;}
 if(artifact){for(const c of component.contours)removedSet.add(c);stats.removedComponents++;stats.recoloredAreaPx2+=area;removed.push(...component.contours.map(c=>c.d));}else kept.push(...component.contours.map(c=>c.d));}
 const ordered=contours.filter(c=>!removedSet.has(c)).map(c=>c.d);if(ordered.length)result.set(fill,ordered);else result.delete(fill);}
 stats.recoloredAreaPx2=Math.round(stats.recoloredAreaPx2*100)/100;stats.removedRegionsD=removed.join(' ');return {groups:result,stats};}
